import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { useTranslation } from 'react-i18next';
import toast from 'react-hot-toast';
import Navbar from '../../components/Navbar';

const RegisterPage = () => {
    const { register } = useAuth();
    const { t } = useTranslation();
    const navigate = useNavigate();
    const [form, setForm] = useState({ name: '', email: '', password: '', phone: '', languagePreference: 'en' });
    const [loading, setLoading] = useState(false);
    const [errors, setErrors] = useState([]);

    const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setErrors([]);
        try {
            await register(form);
            toast.success('Account created successfully!');
            navigate('/citizen/dashboard');
        } catch (err) {
            const apiErrors = err.response?.data?.errors || [];
            const msg = err.response?.data?.message || 'Registration failed';
            setErrors(apiErrors.length ? apiErrors.map(e => e.message) : [msg]);
        } finally { setLoading(false); }
    };

    return (
        <div className="min-h-screen bg-gradient-to-br from-primary-50 via-white to-blue-50">
            <Navbar />
            <div className="flex items-center justify-center py-12 px-4">
                <div className="w-full max-w-md">
                    <div className="text-center mb-8">
                        <div className="inline-flex items-center justify-center w-14 h-14 bg-primary-600 rounded-2xl mb-4 shadow-lg">
                            <span className="text-white text-2xl font-bold">eN</span>
                        </div>
                        <h1 className="text-2xl font-bold text-gray-900">{t('auth.registerTitle')}</h1>
                        <p className="text-gray-500 text-sm mt-1">Join e-Nagar Suraksha as a citizen</p>
                    </div>

                    <div className="card">
                        {errors.length > 0 && (
                            <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg">
                                {errors.map((e, i) => <p key={i} className="text-sm text-red-600">{e}</p>)}
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">{t('auth.name')}</label>
                                <input name="name" type="text" required value={form.name} onChange={handleChange}
                                    className="input-field" placeholder="Rajesh Kumar" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">{t('auth.email')}</label>
                                <input name="email" type="email" required value={form.email} onChange={handleChange}
                                    className="input-field" placeholder="you@example.com" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">{t('auth.phone')}</label>
                                <input name="phone" type="tel" value={form.phone} onChange={handleChange}
                                    className="input-field" placeholder="9876543210" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">{t('auth.password')}</label>
                                <input name="password" type="password" required value={form.password} onChange={handleChange}
                                    className="input-field" placeholder="Min 8 chars with upper, lower & number" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Preferred Language</label>
                                <select name="languagePreference" value={form.languagePreference} onChange={handleChange} className="input-field">
                                    <option value="en">English</option>
                                    <option value="hi">हिंदी (Hindi)</option>
                                    <option value="te">తెలుగు (Telugu)</option>
                                </select>
                            </div>
                            <button type="submit" disabled={loading} className="btn-primary w-full mt-2">
                                {loading ? 'Creating account...' : t('auth.registerBtn')}
                            </button>
                        </form>

                        <p className="mt-4 text-center text-sm text-gray-500">
                            {t('auth.hasAccount')}{' '}
                            <Link to="/login" className="text-primary-600 hover:text-primary-700 font-medium">Sign in</Link>
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default RegisterPage;
